import calendar
import datetime

_WEEKDAYS = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}


def recur(start: str, rule: str, count: int) -> list[str]:
    s = datetime.date.fromisoformat(start)
    tokens = rule.split()
    kind = tokens[0]
    out: list[str] = []

    if kind == "DAILY":
        k = int(tokens[1])
        d = s
        while len(out) < count:
            out.append(d.isoformat())
            d += datetime.timedelta(days=k)

    elif kind == "WEEKLY":
        k = int(tokens[1])
        wanted = sorted({_WEEKDAYS[x] for x in tokens[2].split(",")})
        monday = s - datetime.timedelta(days=s.weekday())
        w = 0
        while len(out) < count:
            if w % k == 0:
                base = monday + datetime.timedelta(weeks=w)
                for wd in wanted:
                    d = base + datetime.timedelta(days=wd)
                    if d >= s:
                        out.append(d.isoformat())
                        if len(out) >= count:
                            break
            w += 1

    elif kind == "MONTHLY" and len(tokens) == 3:
        k = int(tokens[1])
        target = int(tokens[2])
        j = 0
        while len(out) < count:
            m = s.year * 12 + (s.month - 1) + j * k
            y, mo = divmod(m, 12)
            mo += 1
            dim = calendar.monthrange(y, mo)[1]
            if target == -1:
                day = dim
            elif target <= dim:
                day = target
            else:
                day = None
            if day is not None:
                d = datetime.date(y, mo, day)
                if d >= s:
                    out.append(d.isoformat())
            j += 1

    elif kind == "MONTHLY":
        k = int(tokens[1])
        n = int(tokens[2])
        wd = _WEEKDAYS[tokens[3]]
        j = 0
        while len(out) < count:
            m = s.year * 12 + (s.month - 1) + j * k
            y, mo = divmod(m, 12)
            mo += 1
            dim = calendar.monthrange(y, mo)[1]
            if n == -1:
                last = datetime.date(y, mo, dim)
                back = (last.weekday() - wd) % 7
                day = dim - back
            else:
                first = datetime.date(y, mo, 1)
                offset = (wd - first.weekday()) % 7
                day = 1 + offset + 7 * (n - 1)
            if 1 <= day <= dim:
                d = datetime.date(y, mo, day)
                if d >= s:
                    out.append(d.isoformat())
            j += 1

    elif kind == "YEARLY":
        k = int(tokens[1])
        mm, dd = map(int, tokens[2].split("-"))
        j = 0
        while len(out) < count:
            y = s.year + j * k
            try:
                d = datetime.date(y, mm, dd)
            except ValueError:
                d = None
            if d is not None and d >= s:
                out.append(d.isoformat())
            j += 1

    return out
